import sys

def main():
    input_line = sys.stdin.readline().strip()
    parts = input_line.split()
    n = int(parts[0])
    m = int(parts[1])
    if n > m:
        n, m = m, n
    if n == 1:
        x = m % 6
        if x <= 3:
            print(m - x)
        elif x == 4:
            print(m - 2)
        else:
            print(m - 1)
        return
    if n <= 5 and m <= 30:
        from functools import lru_cache

        @lru_cache(None)
        def go(row, col, mask):
            if row == m:
                return 0 if mask == 0 else float('-inf')
            if col == n:
                return go(row + 1, 0, mask)
            if (mask & 1) == 1:
                return go(row, col + 1, mask >> 1)
            res = go(row, col + 1, mask >> 1)
            res = max(res, go(row, col + 1, (mask >> 1) + (1 << (3 * n - 1))) + 2)
            if col != 0 and ((mask >> (2 * n - 1)) & 1) == 0:
                res = max(res, go(row, col + 1, (mask >> 1) + (1 << (2 * n - 2))) + 2)
            if col != n - 1 and ((mask >> (2 * n + 1)) & 1) == 0:
                res = max(res, go(row, col + 1, (mask >> 1) + (1 << (2 * n))) + 2)
            if col >= 2 and ((mask >> (n - 2)) & 1) == 0:
                res = max(res, go(row, col + 1, (mask >> 1) + (1 << (n - 3))) + 2)
            if col < n - 1 and ((mask >> (n + 2)) & 1) == 0:
                res = max(res, go(row, col + 1, (mask >> 1) + (1 << (n + 1))) + 2)
            return res

        print(go(0, 0, 0))
    else:
        print(n * m - (n * m) % 2)

